    internal static IReadOnlyList<string> Mismatches(JsonObject catalog, IEnumerable<string> sources)
    {
        var available = BalanceCombatData.Array(catalog["sources"]).OfType<JsonObject>()
            .ToDictionary(row => BalanceCombatData.Text(row["path"]), row => BalanceCombatData.Text(row["hash"]), StringComparer.Ordinal);
        return sources.Concat(Common).Where(path => path.StartsWith("10_plugin/", StringComparison.Ordinal)).Distinct(StringComparer.Ordinal).Where(path =>
            !Hashes.TryGetValue(path, out var expected) || !available.TryGetValue(path, out var actual)
            || actual != expected).ToArray();
    }
